algorithms.pseudocode:
function RegularRepresentation(G):
    n <- |G|
    perms <- empty array of size n
    for g in G.elements:
        perm <- array of size n
        for x in G.elements:
            perm[x] <- G.op(g, x)
        perms[g] <- perm
    return perms

Complexity: O(n^2) time, O(n^2) space

function ComputeOrbit(perms, x):
    orbit <- {x}
    frontier <- [x]
    while frontier is non-empty:
        current <- frontier.pop()
        for sigma in perms:
            y <- sigma(current)
            if y not in orbit:
                orbit.add(y)
                frontier.append(y)
    return orbit

Complexity: O(n * |G|) time, O(n) space
